import mujoco
import numpy as np

from src.task_config import TASK_CFG


def make_cheat_arm_stage(model, data, delay_s=2.0, task_cfg=TASK_CFG):
    """Makes an arm stage that cheats: it teleports the beaker onto the hotplate after a delay.

    The beaker is placed with its origin (its bottom centre) 2 mm above the "hotplate_top" site, upright, with zero velocity.
    The stage never commands anything.

    Args:
        model (mujoco.MjModel): The compiled model; it must have the free joint "task_beaker_free".
        data (mujoco.MjData): The simulation data that is modified when the beaker is teleported.
        delay_s (float): Seconds between the stage's first step and the teleport. Defaults to 2.0.
        task_cfg (dict): The task configuration. Not used. Defaults to TASK_CFG.

    Returns:
        dict: An arm stage {"name": "cheat", "step": step(obs) -> None, "state": state}. state["first_step"] is the simulation
        time of the first step and state["teleported_at"] the time of the teleport (both None until they happen).
    """
    jq = int(model.joint("task_beaker_free").qposadr[0])
    jv = int(model.joint("task_beaker_free").dofadr[0])
    state = {"first_step": None, "teleported_at": None}

    def step(obs):
        """Teleports the beaker once delay_s seconds have passed since the first call.

        Reads obs["time"] and changes state["first_step"] and state["teleported_at"] in the enclosing scope; writes the beaker's qpos
        and qvel in `data` and calls mujoco.mj_forward.

        Args:
            obs (dict): The loop's observation; only obs["time"] (simulation time in seconds) is used.

        Returns:
            None: This stage never commands anything.
        """
        if state["first_step"] is None:
            state["first_step"] = obs["time"]
        if state["teleported_at"] is None and obs["time"] - state["first_step"] >= delay_s:
            top = data.site("hotplate_top").xpos
            data.qpos[jq:jq + 7] = [top[0], top[1], top[2] + 0.002, 1, 0, 0, 0]      # the beaker's origin is its bottom centre
            data.qvel[jv:jv + 6] = 0.0
            mujoco.mj_forward(model, data)
            state["teleported_at"] = obs["time"]
            print(f"[cheat] t={obs['time']:.2f} s: beaker teleported onto the hotplate (TEST ONLY)")
        return None

    return {"name": "cheat", "step": step, "state": state}


def make_grasp_force_stage(model, data, forces=(1.0, 2.0, None), task_cfg=TASK_CFG, move_s=4.0, settle_s=1.0, close_s=3.0, open_s=2.0, measure_s=1.0):
    """Makes an arm stage that measures how hard the gripper presses on the beaker for several force limits.

    The timeline is: move (ready pose to grasp pose, minimum-jerk interpolation, gripper open), settle (gripper open), then for
    every entry of `forces`: close (gripper closing on the beaker; the contact forces are sampled during the last measure_s
    seconds) and open (gripper open again; the samples of the closing are summarised at its first tick). After the timeline the
    stage returns None for ever.

    Args:
        model (mujoco.MjModel): The compiled model; it needs the bodies "task_beaker" and "openarm_<arm>_hand", the finger bodies
            "openarm_<arm>_*finger" and the actuators "<arm>_finger1_ctrl" and "<arm>_finger2_ctrl".
        data (mujoco.MjData): The simulation data, read for contacts and actuator forces.
        forces (tuple): Gripper force limits to test, in newtons per finger, one closing each. An entry of None means a plain
            position 0 command, i.e. the force ceiling. Defaults to (1.0, 2.0, None).
        task_cfg (dict): The task configuration; uses "arm", "ready_q", "grasp_q" (radians) and "finger_open" (metres, 0.044 if
            missing). Defaults to TASK_CFG.
        move_s (float): Duration of the move to the grasp pose, in seconds. Defaults to 4.0.
        settle_s (float): Pause after the move, in seconds. Defaults to 1.0.
        close_s (float): Duration of each closing, in seconds. Defaults to 3.0.
        open_s (float): Duration of each opening, in seconds. Defaults to 2.0.
        measure_s (float): The last this many seconds of each closing are sampled, in seconds. Defaults to 1.0.

    Returns:
        dict: An arm stage {"name": "grasp_force_test", "step": step(obs) -> command or None, "state": state}. state holds
        "t0" (simulation time of the first step), "results" (list with one dict per finished closing, see _summarise()),
        "samples" (the samples of the closing in progress), "segments" (the timeline as (kind, duration_s, force) tuples),
        "total_s" (length of the timeline in seconds), and, once a closing has been sampled, "normal_sum" and "axis_z" (the latest
        values from contact_forces()).
    """
    arm = task_cfg["arm"]
    ready, grasp = np.array(task_cfg["ready_q"], float), np.array(task_cfg["grasp_q"], float)
    open_g = task_cfg["finger_open"] if "finger_open" in task_cfg else 0.044
    fingers = {b for b in range(model.nbody) if model.body(b).name.startswith(f"openarm_{arm}_") and model.body(b).name.endswith("finger")}
    beaker = model.body("task_beaker").id
    f_act = [model.actuator(f"{arm}_finger{k}_ctrl").id for k in (1, 2)]
    f_q = [int(model.jnt_qposadr[model.actuator_trnid[a, 0]]) for a in f_act]
    f6 = np.zeros(6)
    # timeline
    segs, t = [("move", move_s, None), ("settle", settle_s, None)], 0.0
    for F in forces:
        segs += [("close", close_s, F), ("open", open_s, None)]
    state = {"t0": None, "results": [], "samples": [], "segments": segs, "total_s": sum(d for _, d, _ in segs)}

    hand = model.body(f"openarm_{arm}_hand").id

    def contact_forces():
        """Measures what each finger presses on the beaker with, in newtons.

        The contact forces between a finger body and the beaker are summed as vectors in the world frame and projected on the
        closing axis (the hand's y axis). The sum of the contacts' normal magnitudes, which counts tilted contact points and edge
        contacts more than once, is stored in state["normal_sum"] for comparison, and the world z component of the closing axis
        in state["axis_z"] (both are overwritten on every call).

        Returns:
            dict: Finger body id (int) -> absolute force along the closing axis in newtons (float), for every finger that touches
            the beaker.
        """
        axis = data.xmat[hand].reshape(3, 3)[:, 1]
        out, normal_sum = {}, {}
        for i in range(data.ncon):
            c = data.contact[i]
            b1, b2 = int(model.geom_bodyid[c.geom1]), int(model.geom_bodyid[c.geom2])
            if (b1 in fingers and b2 == beaker) or (b2 in fingers and b1 == beaker):
                mujoco.mj_contactForce(model, data, i, f6)
                fb = b1 if b1 in fingers else b2
                world = c.frame.reshape(3, 3).T @ f6[:3]               # contact frame (normal, tangents) -> world
                out[fb] = out.get(fb, 0.0) + float(world @ axis)
                normal_sum[fb] = normal_sum.get(fb, 0.0) + abs(float(f6[0]))
        state["normal_sum"] = normal_sum
        state["axis_z"] = float(axis[2])
        return {k: abs(v) for k, v in out.items()}

    def step(obs):
        """Returns the command for the current point of the timeline.

        Sets state["t0"] on the first call. Appends to state["samples"] while a closing is in its measuring window, and moves the
        summary of a finished closing from the samples to state["results"] when the following opening starts.

        Args:
            obs (dict): The loop's observation; uses obs["time"] (seconds) and obs["applied"]["gripper_force"][arm] (the applied
                force limit).

        Returns:
            dict or None: An arms command: during the move {"mode": "arms", "arm_targets": {arm: 7 joint angles in radians},
            "gripper": {arm: finger_open in metres}}; during settle and open {"mode": "arms", "gripper": {arm: finger_open}};
            during a closing {"mode": "arms", "gripper": {arm: 0.0}} for a force of None, else
            {"mode": "arms", "gripper": {arm: {"position": 0.0, "max_force": F}}}. None once the timeline is over.
        """
        if state["t0"] is None:
            state["t0"] = obs["time"]
        el = obs["time"] - state["t0"]
        start = 0.0
        for kind, dur, F in segs:
            if el < start + dur:
                break
            start += dur
        else:
            return None
        local = el - start
        if kind == "move":
            u = min(local / move_s, 1.0)
            q = ready + (grasp - ready) * (10 * u ** 3 - 15 * u ** 4 + 6 * u ** 5)
            return {"mode": "arms", "arm_targets": {arm: [float(v) for v in q]}, "gripper": {arm: open_g}}
        if kind in ("settle", "open"):
            if kind == "open" and state["samples"]:
                state["results"].append(_summarise(state["samples"], segs, state))
                state["samples"] = []
            return {"mode": "arms", "gripper": {arm: open_g}}
        # close
        if local >= close_s - measure_s:
            cf = contact_forces()
            state["samples"].append({"F": F, "contact": dict(cf), "normal_sum": dict(state.get("normal_sum", {})), "axis_z": state.get("axis_z", 0.0), "actuator": [abs(float(data.actuator_force[a])) for a in f_act], "q": [float(data.qpos[a]) for a in f_q],
                                     "time": obs["time"], "cap": obs["applied"]["gripper_force"][arm]})
        return {"mode": "arms", "gripper": {arm: 0.0 if F is None else {"position": 0.0, "max_force": F}}}

    return {"name": "grasp_force_test", "step": step, "state": state}


def _summarise(samples, segs, state):
    """Condenses the samples of one closing into the numbers that experiments/gripper_force_test.py reports.

    Args:
        samples (list[dict]): The samples taken during the measuring window of one closing. Each has "F" (the force limit
            commanded, in newtons (N), or None), "contact" and "normal_sum" (finger body id -> N), "axis_z", "actuator" (the two
            finger actuators' absolute forces, N), "q" (the two finger joint positions, in metres (m)), "time" (seconds) and
            "cap" (the applied force limit, N).
        segs (list): The timeline. Not used.
        state (dict): The stage's state. Not used.

    Returns:
        dict: "max_force_command" (the commanded limit, N or None), "applied_cap" (the applied limit at the last sample, N),
        "contact_normal_N_per_finger_mean" (list: mean force along the closing axis per touching finger, sorted by size, N),
        "closing_axis_z" (mean world z component of the closing axis), "contact_normal_sum_N_per_finger_mean" (the same for the sum
        of the normal magnitudes, N), "contact_normal_N_peak" (largest single-finger force in any sample, N),
        "actuator_force_N_mean" (list of two: mean absolute actuator force per finger, N), "finger_q_mm" (list of two: mean finger
        position, in millimetres (mm)) and "n_fingers_in_contact" (largest number of touching fingers in a sample).
    """
    nf = max(len(sm["contact"]) for sm in samples)
    per_finger = [np.mean([sorted(sm["contact"].values())[i] if len(sm["contact"]) > i else 0.0 for sm in samples]) for i in range(max(nf, 1))]
    ns = [np.mean([sorted(sm["normal_sum"].values())[i] if len(sm["normal_sum"]) > i else 0.0 for sm in samples]) for i in range(max(nf, 1))]
    return {"max_force_command": samples[0]["F"], "applied_cap": samples[-1]["cap"], "contact_normal_N_per_finger_mean": [float(v) for v in per_finger],
            "closing_axis_z": float(np.mean([sm["axis_z"] for sm in samples])), "contact_normal_sum_N_per_finger_mean": [float(v) for v in ns],
            "contact_normal_N_peak": float(max((max(sm["contact"].values()) if sm["contact"] else 0.0) for sm in samples)),
            "actuator_force_N_mean": [float(np.mean([sm["actuator"][i] for sm in samples])) for i in range(2)],
            "finger_q_mm": [1000 * float(np.mean([sm["q"][i] for sm in samples])) for i in range(2)], "n_fingers_in_contact": nf}


def make_kick_source(model, data, phase, delay_s, along_mm, lateral_mm, yaw_deg, task_cfg=TASK_CFG):
    """Makes a test source that displaces the base once, a while after the staging stage entered a given phase.

    The base is moved by editing its free-joint pose in `data` (position along and across the staging heading, then yaw) and
    calling mujoco.mj_forward. Test only.

    Args:
        model (mujoco.MjModel): The compiled model.
        data (mujoco.MjData): The simulation data; qpos[0:7] must be the base's free joint.
        phase (str): The staging phase (obs["policy"]["phase"], for example "PEDESTAL" or "ARMS") in which to kick.
        delay_s (float): Seconds between the phase being first seen and the kick.
        along_mm (float): Displacement along the staging heading in millimetres (mm); positive is toward the bench.
        lateral_mm (float): Displacement to the left of the staging heading, in mm.
        yaw_deg (float): Extra rotation of the base in degrees (counter-clockwise positive).
        task_cfg (dict): The task configuration; uses "staging_yaw" (radians). Defaults to TASK_CFG.

    Returns:
        dict: A source {"name": "kick", "step": step(obs) -> None, "state": state}. state["kicked_at"] is the simulation time of
        the kick (None before it) and state["phase_start"] the time the phase was first seen (None when not in the phase).
    """
    import math
    state = {"kicked_at": None, "phase_start": None}
    gyaw = task_cfg["staging_yaw"]

    def step(obs):
        """Kicks the base once, when the policy has been in `phase` for delay_s seconds.

        Reads obs["policy"] and obs["time"]; changes state["phase_start"] (reset whenever the phase differs) and
        state["kicked_at"]; writes the base pose in `data`; prints one line when it kicks.

        Args:
            obs (dict): The loop's observation; uses obs["time"] (seconds) and obs["policy"]["phase"] (absent in a teleop run).

        Returns:
            None: This source never commands anything.
        """
        ep = obs.get("policy")
        if state["kicked_at"] is not None or not ep:
            return None
        if ep["phase"] != phase:
            state["phase_start"] = None
            return None
        if state["phase_start"] is None:
            state["phase_start"] = obs["time"]
        if obs["time"] - state["phase_start"] >= delay_s:
            a, l = along_mm / 1000.0, lateral_mm / 1000.0
            data.qpos[0] += a * math.cos(gyaw) - l * math.sin(gyaw)
            data.qpos[1] += a * math.sin(gyaw) + l * math.cos(gyaw)
            yaw = 2.0 * math.atan2(data.qpos[6], data.qpos[3]) + math.radians(yaw_deg)
            data.qpos[3:7] = [math.cos(yaw / 2), 0.0, 0.0, math.sin(yaw / 2)]
            mujoco.mj_forward(model, data)
            state["kicked_at"] = obs["time"]
            print(f"[kick] t={obs['time']:.2f} s in {phase}: base displaced by {along_mm:+.0f} mm along, {lateral_mm:+.0f} mm sideways, {yaw_deg:+.1f} deg (TEST ONLY)")
        return None

    return {"name": "kick", "step": step, "state": state}
